'use strict';

const path = require('path');
const os = require('os');
const PptxGenJS = require('pptxgenjs');
const { renderIcon } = require('./icons');

const W = 13.333;
const H = 7.5;

const PALETTES = {
  'moss-amber': {
    bg: '10241A', surface: '183528', ink: 'F3EEE3', muted: 'A7B4A0',
    accent: 'D4A017', onAccent: '10241A', name: 'moss-amber',
  },
  pitch: {
    bg: '111827', surface: '1F2937', ink: 'F8FAFC', muted: '94A3B8',
    accent: 'C9A227', onAccent: '111827', name: 'pitch',
  },
  'night-copper': {
    bg: '14110F', surface: '1E1A17', ink: 'F2EBE3', muted: 'A89888',
    accent: 'C46B3A', onAccent: '14110F', name: 'night-copper',
  },
  'ink-paper': {
    bg: 'F6F1E8', surface: 'FFFFFF', ink: '1A1714', muted: '6F675E',
    accent: '8C2F1B', onAccent: 'F6F1E8', name: 'ink-paper',
