  'ocean-sand': {
    bg: 'F3F0EA', surface: 'FFFFFF', ink: '12323A', muted: '5E737A',
    accent: '2A6F7A', onAccent: 'FFFFFF', name: 'ocean-sand',
  },
};

function pickPalette(subject) {
  const s = String(subject || '');
  if (/融资|路演|pitch|seed|投资|估值/i.test(s)) return 'pitch';
  if (/新能源|光伏|风电|能源|碳|绿色|气候/i.test(s)) return 'moss-amber';
  if (/文化|历史|品牌|故事|杂志/i.test(s)) return 'ink-paper';
  if (/夜|发布会|keynote|科技/i.test(s)) return 'night-copper';
  if (/海|水|金融|研究/i.test(s)) return 'ocean-sand';
  return 'pitch';
}

function fontFace() {
  return os.platform() === 'win32' ? 'Microsoft YaHei' : 'PingFang SC';
}

function hex(v) {
  return String(v || '').replace(/^#/, '').toUpperCase();
}

class Deck {
  constructor(opts = {}) {
    const pal = opts.palette;
    if (pal && typeof pal === 'object') {
      this.pal = { ...PALETTES.pitch, ...pal, bg: hex(pal.bg), surface: hex(pal.surface), ink: hex(pal.ink), muted: hex(pal.muted), accent: hex(pal.accent), onAccent: hex(pal.onAccent || pal.bg) };
    } else {
      this.pal = PALETTES[pal] || PALETTES[pickPalette(opts.subject)];
    }
    this.font = fontFace();
    this.iconDir = path.resolve(opts.iconDir || path.join(process.cwd(), '.pptx-icons'));
    this.icons = {};
    this.pptx = new PptxGenJS();
    this.pptx.defineLayout({ name: 'WIDE', width: W, height: H });
    this.pptx.layout = 'WIDE';
    this.pptx.title = opts.title || '';
    this.pptx.author = 'PABuddy';
    this.pptx.theme = { headFontFace: this.font, bodyFontFace: this.font };
