    s.addTable([head, ...body], {
      x: 0.7, y: 1.3, w: 11.9, h: 5.5,
      colW: headers && headers.length ? Array(headers.length).fill(11.9 / headers.length) : undefined,
      border: [{ pt: 0 }, { pt: 0 }, { pt: 0 }, { pt: 0 }],
      fontFace: this.font,
      fontSize: 13,
      align: 'left',
      valign: 'middle',
    });
    return s;
  }

  quote({ text, attribution } = {}) {
    const s = this._slide();
    s.addShape(this.pptx.ShapeType.rect, {
      x: 0.7, y: 2.4, w: 0.12, h: 2.4,
      fill: { color: this.pal.accent }, line: { color: this.pal.accent },
    });
    this._text(s, '“' + (text || '') + '”', {
      x: 1.15, y: 2.3, w: 11.2, h: 2.2, fontSize: 24, bold: true, color: this.pal.ink,
    });
    if (attribution) {
      this._text(s, attribution, {
        x: 1.15, y: 4.7, w: 11.2, h: 0.45, fontSize: 14, color: this.pal.muted,
      });
    }
    return s;
  }

  close({ title, subtitle } = {}) {
    const s = this.pptx.addSlide();
    s.addShape(this.pptx.ShapeType.rect, {
      x: 0, y: 0, w: W, h: H,
      fill: { color: this.pal.accent }, line: { color: this.pal.accent },
    });
    this._text(s, title || '', {
      x: 1.0, y: 2.6, w: 11.3, h: 1.6, fontSize: 34, bold: true, color: this.pal.onAccent,
    });
    if (subtitle) {
      this._text(s, subtitle, {
        x: 1.0, y: 4.4, w: 11.3, h: 1.0, fontSize: 16, color: this.pal.onAccent,
      });
    }
    return s;
  }

  async save(fileName) {
    const name = String(fileName || 'deck.pptx');
    const out = name.endsWith('.pptx') ? name : `${name}.pptx`;
    await this.pptx.writeFile({ fileName: out });
    return path.resolve(out);
  }
}

function newDeck(opts) {
  return new Deck(opts);
}

module.exports = { newDeck, Deck, PALETTES, pickPalette };

